(function(){
'use strict';
if(document.documentElement.hasAttribute('data-admin')||document.body?.hasAttribute('data-admin')||document.body?.hasAttribute('data-research-audit'))return;
const EXACT=new Set([
'AI-generated','generated by AI','AI summary','AI interpretation','AI commentary','machine-generated','automated note','system note','editorial note','processing note','source-processing note','OCR note','confidence note','verification note','provenance class','internal classification','generated content class','restoration status','review status','ingestion status','draft status','model commentary','assistant commentary','Coming soon','Placeholder','Sample text','Demo content','TODO','Needs review','Pending AI generation','Waiting for OCR','Source missing','Test article','Development version','Temporary text',
'موثّق المصدر 100%','تم التحقق من المصدر','تم اجتياز التحقق','ملاحظة النظام','ملاحظة تحريرية','ملاحظة المعالجة','ملاحظة OCR','درجة الثقة','حالة المراجعة','حالة الاستعادة','حالة الإدخال','حالة المسودة','قيد المراجعة','في انتظار OCR','محتوى تجريبي','نص مؤقت','عنصر نائب'
].map(x=>x.toLowerCase()));
const PREFIX=[
/^ai\s*(summary|interpretation|commentary|note)\s*:/i,
/^model\s+note\s*:/i,
/^editorial\s+pipeline\s+note\s*:/i,
/^our\s+system\s+found\s*:/i,
/^this\s+(article|story|content)\s+was\s+(generated|produced)/i,
/^the\s+following\s+passage\s+was\s+reconstructed/i,
/^confidence\s*:/i,
/^ocr\s+repaired/i,
/^source\s+verification\s+passed/i,
/^generated\s+on\s*:/i,
/^(ملاحظة|تنبيه)\s+(النظام|التحرير|المعالجة|المراجعة|الاستعادة|الإدخال)\s*[:：-]?/,
/^(درجة|نسبة)\s+الثقة\s*[:：-]?/,
/^تم\s+(توليد|إنشاء|إصلاح|استعادة|التحقق|استخراج)\s+.*(آلي|بالذكاء|بواسطة النظام)/,
/^هذه\s+(المادة|القصة|المقالة)\s+.*(مولدة|منشأة آليًا|غير موثقة)/
];
const RAW_ENUM=/\b(SOURCED_EXTRACTED|SOURCE_GROUNDED_SYNTHESIS|LEGACY_UNSOURCED_STORY|GENERATED_UNSOURCED_STORY|REVIEW_REQUIRED|SOURCE_VERIFIED|OCR_PENDING|OCR_REPAIRED)\b/;
const TECH=/\b(aiOriginalSubstantiveContentPercent|sourceCoveragePercent|provenanceStatus|quotationVerification|duplicateCheck|verificationBasis|ocrRef|sourceFingerprint|draftStatus|publicationStatus|canonicalEditorialSlot)\b/;
const SKIP='script,style,pre,code,textarea,input,select,option,[data-public-meta-allowed],[data-keep-operational],.admin,.audit,.research-audit';
function norm(s){return String(s||'').replace(/\s+/g,' ').trim()}
function forbidden(t){const x=norm(t);if(!x)return false;const low=x.toLowerCase();if(EXACT.has(low))return true;if(RAW_ENUM.test(x)||TECH.test(x))return true;return PREFIX.some(r=>r.test(x))}
function cleanNode(el){if(!(el instanceof Element)||el.matches(SKIP)||el.closest(SKIP))return;
 if(el.matches('.ep-integrity,.ep-badge,[data-internal-status],[data-provenance-class],[data-pipeline-note],[data-debug],[data-placeholder]')){el.remove();return}
 const direct=[...el.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE);
 for(const n of direct){if(forbidden(n.nodeValue))n.remove()}
 if(!el.children.length&&forbidden(el.textContent)){el.remove();return}
}
function sweep(root=document){if(root instanceof Element)cleanNode(root);root.querySelectorAll?.('body *').forEach(cleanNode)}
function start(){sweep(document);const mo=new MutationObserver(ms=>{for(const m of ms)for(const n of m.addedNodes){if(n.nodeType===1)sweep(n)}});mo.observe(document.documentElement,{subtree:true,childList:true});setTimeout(()=>mo.disconnect(),60000)}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start();
window.ProphetPublicPagePurity={run:()=>sweep(document),isForbidden:forbidden};
})();
